//! Generated editor-grammar contract tests.
//!
//! The committed package under `site/packages/highlighting` is a golden:
//! `committed_package_matches_the_generator` byte-compares every file, so a
//! hand edit (or a vocabulary change without regeneration) fails here. The
//! remaining tests pin the grammar/config shape and prove the vocabulary is
//! derived from the SH1 metadata rather than a second hand-written list.
//!
//! Regenerate after a deliberate metadata change, then read the diff — the
//! generated files are the editor contract:
//!
//! ```sh
//! cargo run -q -p phero-cli -- grammar --out site/packages/highlighting
//! ```

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use phero_highlight::{
    all_metadata, check_grammars, class_scope, generate_grammars, metadata_for, write_grammars,
    GrammarProblemKind, HighlightClass, Surface, GRAMMAR_FORMAT_VERSION,
};
use serde_json::Value;

fn package_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../site/packages/highlighting")
}

fn site_surfaces() -> Vec<(String, String)> {
    let json: Value = serde_json::from_str(include_str!("../../../site/data/surfaces.json"))
        .expect("the site surface catalogue is valid JSON");
    json["surfaces"]
        .as_array()
        .expect("surfaces array")
        .iter()
        .map(|entry| {
            (
                entry["id"].as_str().expect("id").to_string(),
                entry["extension"].as_str().expect("extension").to_string(),
            )
        })
        .collect()
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|error| panic!("parse {}: {error}", path.display()))
}

/// Extracts the words from the first `(?:a|b|c)` alternation in a pattern.
fn alternation_words(pattern: &str) -> BTreeSet<String> {
    let start = pattern
        .find("(?:")
        .unwrap_or_else(|| panic!("pattern has no alternation: {pattern}"));
    let rest = &pattern[start + 3..];
    let end = rest
        .find(')')
        .unwrap_or_else(|| panic!("unterminated alternation: {pattern}"));
    rest[..end]
        .split('|')
        .map(|word| word.replace('\\', ""))
        .collect()
}

fn rule_words(grammar: &Value, key: &str) -> BTreeSet<String> {
    let pattern = grammar["repository"][key]["patterns"][0]["match"]
        .as_str()
        .unwrap_or_else(|| panic!("repository `{key}` has no match rule"));
    alternation_words(pattern)
}

#[test]
fn every_site_surface_has_a_grammar_and_configuration() {
    let site = site_surfaces();
    assert_eq!(site.len(), 10, "the site lists ten surfaces");

    for (id, extension) in site {
        let surface = Surface::from_id(&id).unwrap_or_else(|| panic!("unknown surface `{id}`"));
        assert_eq!(extension, format!(".{}", surface.extension()));

        let grammar = read_json(
            &package_dir()
                .join("grammars")
                .join(format!("{id}.tmLanguage.json")),
        );
        assert_eq!(grammar["formatVersion"], GRAMMAR_FORMAT_VERSION);
        assert_eq!(grammar["name"], id);
        assert_eq!(grammar["scopeName"], format!("source.{id}"));
        assert_eq!(grammar["fileTypes"][0], extension);
        assert_eq!(grammar["aliases"][0], id);
        let comment = grammar["comment"].as_str().expect("grammar comment");
        assert!(
            comment.contains("Generated by pherolang"),
            "{id}: {comment}"
        );
        assert!(comment.contains("do not edit"), "{id}: {comment}");
        assert!(
            grammar["patterns"]
                .as_array()
                .is_some_and(|patterns| !patterns.is_empty()),
            "{id} has no top-level patterns"
        );
        assert!(
            grammar["repository"]
                .as_object()
                .is_some_and(|repository| !repository.is_empty()),
            "{id} has an empty repository"
        );

        let configuration = read_json(
            &package_dir()
                .join("language-configurations")
                .join(format!("{id}.json")),
        );
        assert_eq!(configuration["formatVersion"], GRAMMAR_FORMAT_VERSION);
        let comment = configuration["comment"]
            .as_str()
            .expect("configuration comment");
        assert!(comment.contains("Generated by pherolang"));
        assert!(comment.contains("do not edit"));
    }
}

#[test]
fn committed_package_matches_the_generator() {
    let dir = package_dir();
    if std::env::var_os("PHERO_UPDATE_FIXTURES").is_some() {
        write_grammars(&dir).expect("write the generated grammar package");
    }
    match check_grammars(&dir) {
        Ok(()) => {}
        Err(problems) => {
            let report = problems
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join("\n");
            panic!("committed grammar package is stale:\n{report}");
        }
    }
}

#[test]
fn generation_is_deterministic() {
    let first = generate_grammars();
    let second = generate_grammars();
    assert_eq!(first, second);
}

#[test]
fn grammar_and_configuration_files_are_deterministic_paths() {
    let files = generate_grammars();
    let paths: Vec<&str> = files.iter().map(|file| file.path.as_str()).collect();
    let sorted = {
        let mut sorted = paths.clone();
        sorted.sort_unstable();
        sorted
    };
    assert_eq!(paths, sorted, "generated files are path-sorted");
    assert_eq!(files.len(), 1 + Surface::ALL.len() * 2);
}

#[test]
fn vocabulary_comes_from_the_metadata() {
    for metadata in all_metadata() {
        let grammar = read_json(
            &package_dir()
                .join("grammars")
                .join(format!("{}.tmLanguage.json", metadata.id)),
        );

        assert_eq!(
            rule_words(&grammar, "keywords"),
            metadata
                .keywords
                .iter()
                .map(|word| (*word).to_string())
                .collect::<BTreeSet<_>>(),
            "{} keyword rule drifted from the metadata",
            metadata.id
        );
        assert_eq!(
            rule_words(&grammar, "literals"),
            metadata
                .literals
                .iter()
                .map(|word| (*word).to_string())
                .collect::<BTreeSet<_>>(),
            "{} literal rule drifted from the metadata",
            metadata.id
        );
        assert_eq!(
            rule_words(&grammar, "builtinTypes"),
            metadata
                .builtin_types
                .iter()
                .map(|word| (*word).to_string())
                .collect::<BTreeSet<_>>(),
            "{} builtin-type rule drifted from the metadata",
            metadata.id
        );

        if metadata.contextual.is_empty() {
            assert!(
                grammar["repository"].get("contextualWords").is_none(),
                "{} has a contextual rule but no contextual words",
                metadata.id
            );
        } else {
            assert_eq!(
                rule_words(&grammar, "contextualWords"),
                metadata
                    .contextual
                    .iter()
                    .map(|word| (*word).to_string())
                    .collect::<BTreeSet<_>>(),
                "{} contextual rule drifted from the metadata",
                metadata.id
            );
            let pattern = grammar["repository"]["contextualWords"]["patterns"][0]["match"]
                .as_str()
                .expect("contextual match rule");
            assert!(
                pattern.starts_with(r"^[\t ]*"),
                "{} contextual words must be line-start only, not global keywords: {pattern}",
                metadata.id
            );
        }
    }
}

#[test]
fn representative_declaration_words_are_pinned_to_their_scopes() {
    let pins = [
        ("mox", "package", HighlightClass::Namespace),
        ("mox", "class", HighlightClass::Type),
        ("actor", "actor", HighlightClass::Type),
        ("evt", "event", HighlightClass::Type),
        ("dmn", "decision_model", HighlightClass::Namespace),
        ("uc", "usecase", HighlightClass::Function),
        ("cmmn", "case", HighlightClass::Namespace),
        ("ifml", "view", HighlightClass::Type),
        ("deploy", "component", HighlightClass::Type),
        ("deploy", "deployment", HighlightClass::Function),
    ];

    for (id, word, class) in pins {
        let surface = Surface::from_id(id).expect("known surface");
        let metadata = metadata_for(surface);
        let expected = metadata
            .declarations
            .iter()
            .find(|(declared, _)| *declared == word)
            .map(|(_, class)| *class);
        assert_eq!(expected, Some(class), "{id} `{word}` declaration class");

        let grammar = read_json(
            &package_dir()
                .join("grammars")
                .join(format!("{id}.tmLanguage.json")),
        );
        let patterns = grammar["repository"]["declarations"]["patterns"]
            .as_array()
            .unwrap_or_else(|| panic!("{id} has no declaration patterns"));
        let prefix = format!(r"^[\t ]*({word})(?:\s+)");
        let rule = patterns
            .iter()
            .find(|rule| {
                rule["match"]
                    .as_str()
                    .is_some_and(|pattern| pattern.starts_with(&prefix))
            })
            .unwrap_or_else(|| panic!("{id} has no `{word}` declaration rule"));

        assert_eq!(
            rule["captures"]["1"]["name"],
            class_scope(HighlightClass::Keyword),
            "{id} `{word}` must be keyword-scoped"
        );
        assert_eq!(
            rule["captures"]["2"]["name"],
            class_scope(class),
            "{id} `{word}` name must be `{}`-scoped",
            class.as_str()
        );
    }
}

#[test]
fn language_configurations_are_structural_and_comment_aware() {
    for metadata in all_metadata() {
        let configuration = read_json(
            &package_dir()
                .join("language-configurations")
                .join(format!("{}.json", metadata.id)),
        );
        assert_eq!(configuration["comments"]["lineComment"], "//");
        if metadata.lexer == phero_highlight::LexerKind::Ifml {
            assert!(
                configuration["comments"].get("blockComment").is_none(),
                "`.ifml` has no block comments"
            );
        } else {
            assert_eq!(configuration["comments"]["blockComment"][0], "/*");
            assert_eq!(configuration["comments"]["blockComment"][1], "*/");
        }

        let brackets = configuration["brackets"]
            .as_array()
            .expect("brackets array");
        for pair in [["{", "}"], ["[", "]"], ["(", ")"]] {
            assert!(
                brackets
                    .iter()
                    .any(|entry| entry[0] == pair[0] && entry[1] == pair[1]),
                "{} is missing the {} bracket pair",
                metadata.id,
                pair[0]
            );
        }

        let auto = configuration["autoClosingPairs"]
            .as_array()
            .expect("autoClosingPairs array");
        assert!(
            auto.iter()
                .any(|entry| entry["open"] == "{" && entry["close"] == "}"),
            "{} does not auto-close braces",
            metadata.id
        );
        let quote = auto
            .iter()
            .find(|entry| entry["open"] == "\"")
            .unwrap_or_else(|| panic!("{} has no string auto-close", metadata.id));
        assert_eq!(quote["close"], "\"");
        assert!(quote["notIn"]
            .as_array()
            .is_some_and(|not_in| not_in.iter().any(|value| value == "string")));

        let surrounding = configuration["surroundingPairs"]
            .as_array()
            .expect("surroundingPairs array");
        assert!(surrounding
            .iter()
            .any(|entry| entry["open"] == "{" && entry["close"] == "}"));
        assert!(surrounding
            .iter()
            .any(|entry| entry["open"] == "\"" && entry["close"] == "\""));

        let word_pattern = configuration["wordPattern"]
            .as_str()
            .expect("wordPattern string");
        assert!(
            word_pattern.contains("[A-Za-z"),
            "{} word pattern",
            metadata.id
        );
        assert!(
            configuration.get("indentationRules").is_none(),
            "{} ships no untested indentation heuristic",
            metadata.id
        );
    }
}

#[test]
fn generated_files_have_no_absolute_paths_or_timestamps() {
    for file in generate_grammars() {
        assert!(
            !file.contents.contains("/home/") && !file.contents.contains("C:\\"),
            "{} embeds an absolute path",
            file.path
        );
        for marker in ["\"generatedAt\"", "\"timestamp\""] {
            assert!(
                !file.contents.contains(marker),
                "{} embeds `{marker}`",
                file.path
            );
        }
    }
}

#[test]
fn check_reports_hand_edits_missing_files_and_extra_copies() {
    let dir = std::env::temp_dir().join(format!("phero-highlight-grammar-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    write_grammars(&dir).expect("write a scratch grammar package");
    check_grammars(&dir).expect("freshly written package checks clean");

    let grammar = dir.join("grammars/mox.tmLanguage.json");
    let original = std::fs::read_to_string(&grammar).expect("read grammar");
    std::fs::write(&grammar, format!("{original} ")).expect("hand edit a grammar");
    let problems = check_grammars(&dir).expect_err("a hand edit is stale");
    assert_eq!(
        problems
            .iter()
            .filter(|problem| problem.kind == GrammarProblemKind::Stale)
            .count(),
        1,
        "{problems:?}"
    );

    std::fs::write(&grammar, &original).expect("restore grammar");
    std::fs::remove_file(dir.join("language-configurations/ifml.json"))
        .expect("remove a configuration");
    let problems = check_grammars(&dir).expect_err("a missing file is reported");
    assert_eq!(
        problems
            .iter()
            .filter(|problem| problem.kind == GrammarProblemKind::Missing)
            .count(),
        1,
        "{problems:?}"
    );

    write_grammars(&dir).expect("restore the package");
    std::fs::write(
        dir.join("grammars/legacy.tmLanguage.json"),
        "{\"name\":\"legacy\"}\n",
    )
    .expect("add an unexpected grammar");
    let problems = check_grammars(&dir).expect_err("an extra grammar is unexpected");
    assert_eq!(
        problems
            .iter()
            .filter(|problem| problem.kind == GrammarProblemKind::Unexpected)
            .count(),
        1,
        "{problems:?}"
    );

    std::fs::remove_dir_all(&dir).expect("clean scratch package");
}
